function html(value){const url=lookup.get(key(value));return '<span class="game-picture'+(url?' art-pending':'')+'">'+(url?'<img class="game-illustration" src="'+url+'" alt="" aria-hidden="true" width="144" height="144" draggable="false">':'')+'<span class="picture-text">'+esc(value)+'</span></span>'}
function ready(image){if(!image.matches?.('img.game-illustration'))return;const show=()=>{if(image.naturalWidth>0){image.parentElement.classList.remove('art-pending');image.parentElement.classList.add('has-art')}};if(image.decode)image.decode().then(show,()=>{});else show()}
document.addEventListener('load',e=>ready(e.target),true);
const watch=new MutationObserver(records=>{if(!window.document)return;for(const r of records)for(const node of r.addedNodes)if(node.nodeType===1){const images=node.matches('img.game-illustration')?[node]:node.querySelectorAll('img.game-illustration');for(const image of images)if(image.complete)ready(image)}});watch.observe(document.documentElement,{childList:true,subtree:true});
document.addEventListener('error',e=>{if(e.target.matches?.('img.game-illustration'))e.target.parentElement.classList.remove('has-art')},true);
