 overlay(base(s)+'<section class="pilot-ready"><h3>'+esc(activityName(s.mode))+'</h3><p>'+T('Take a comfortable seat. Everyone starts after the facilitator’s countdown.','请舒适就座，带领者倒数后大家一起开始。')+'</p><p class="pilot-count" role="status">'+(s.pilot.releaseAt?T('Starting in ','将在 ')+Math.max(1,Math.ceil((s.pilot.releaseAt-s.serverTime)/1000))+T(' seconds',' 秒后开始'):ready+'/'+members.length+' '+T('ready and connected','已准备并连接'))+'</p><div id="mpRoster">'+people(s)+'</div>'+(!mine?.beganAt?'<button class="btn main" id="pilotReady">'+T('I’m ready','我准备好了')+'</button>':'<p>'+T('You are ready','您已准备好')+'</p>')+(s.host&&!s.pilot.releaseAt?'<button class="btn main" id="pilotTogether"'+(ready!==members.length?' disabled':'')+'>'+T('Start together','一起开始')+'</button>':'')+'</section><button class="btn" id="mpExit">'+T('Back to garden · stay joined','返回花园 · 保留参与')+'</button><p id="multiError" role="alert"></p>');
 if($('pilotReady'))$('pilotReady').onclick=()=>beginRound($('pilotReady'),accept);
 if($('pilotTogether'))$('pilotTogether').onclick=()=>action(async()=>accept(await api('startTogether',{...room,round:s.round})));
