 overlay('<h2>'+T('Rename current player','修改当前玩家名称')+'</h2><label class="lab">'+T('Your name','你的名称')+'<input id="gardenName" maxlength="20" autocomplete="nickname" value="'+esc(me().name)+'"></label><p class="tip">'+T('Renaming keeps this player’s existing progress. For a different person, choose or add a player below. Each player has a separate garden and history on this device.','修改名称会保留当前玩家的进度。其他人请在下方选择或添加玩家；每位玩家在此设备上有独立的花园和记录。')+'</p><div class="row"><button class="btn main" id="gardenNameSave">'+T('Save name','保存名称')+'</button><button class="btn" id="gardenNameProfiles">'+T('Choose or add a player','选择或添加玩家')+'</button><button class="btn" id="gardenNameDone">'+T('Done','完成')+'</button></div><p id="gardenNameStatus" role="status"></p>');
