function beginAnswer(){const g=active;if(g.type==='recall'&&g.delay){g.phase='delay';g.remaining=g.delay;g.viewElapsed=0;g.settleRemaining=0;render();runClock()}else{g.phase='answer';render();$('gaAnswer')?.focus()}}
function beginView(){active.phase='view';active.remaining=active.seconds;active.settleRemaining=GAME_SETTLE_MS;active.viewElapsed=0;render();runClock()}
function runClock(){clearInterval(clock);clock=setInterval(()=>{if(!active||active.paused||document.hidden)return;if(active.settleRemaining>0){active.settleRemaining-=100;return}active.viewElapsed=(active.viewElapsed||0)+100;if(active.viewElapsed<1000)return;active.viewElapsed=0;active.remaining--;const counter=$('gaCountdown');if(counter)counter.textContent=T(active.remaining+' seconds',active.remaining+' 秒');if(active.remaining<=0){clearInterval(clock);if(active.phase==='view')beginAnswer();else{active.phase='answer';render();$('gaAnswer')?.focus()}}},100)}
function svgShape(shape,cls=''){return '<svg class="ga-shape '+cls+'" viewBox="0 0 100 100" aria-hidden="true"><polyline points="'+shape.p.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
function shell(content){$('mp').innerHTML='<section class="ga-game">'+content+'<p id="gaNotice" class="ga-notice" role="status">'+esc(active.notice)+'</p></section>'}
function render(){const g=active;if(!g)return;if(g.type==='pets'){shell('<p>'+T('Choose a friend. Tap or gently stroke your pet. Watch them explore at their own pace.','选择伙伴，轻点或轻柔抚摸，让它自在探索。')+'</p><div id="gaPet"></div><div class="ga-actions">'+button('gaPetDone','Back to All Games','返回所有游戏')+'</div>');pet=window.createMochiWidget($('gaPet'),{asset:'pets/mochi-sprites.webp',language:()=>save.lang,motionAllowed:()=>!g.paused&&window.MindGardenMotion?.effectiveMode()!=='off'});$('gaPetDone').onclick=exit;return}
 if(g.type==='dots')return renderDots(g);if(g.type==='links')return renderLinks(g);if(g.type==='spot')return renderSpot(g);
 if(g.phase==='delay'){shell('<h2>'+T('Keep the sequence in mind','请记住顺序')+'</h2><p id="gaCountdown">'+T(g.remaining+' seconds',g.remaining+' 秒')+'</p>');return}
 if(g.phase==='ready'){shell('<h2>'+T('Ready to remember?','准备好记忆了吗？')+'</h2><p>'+T('The picture or sequence appears only after you press Ready. You will have ','点击准备后才会显示图形或顺序。您有 ')+g.seconds+T(' seconds. Answer without a timer.',' 秒观看。回答不限时。')+'</p><div class="ga-actions">'+button('gaReady','Ready','准备')+'</div>');$('gaReady').onclick=beginView;return}
 if(g.phase==='view'){shell('<p id="gaCountdown">'+T(g.remaining+' seconds',g.remaining+' 秒')+'</p>'+(g.type==='drawmemory'?svgShape(g.shape):'<div class="ga-sequence">'+g.answer.map(x=>'<span>'+esc(x)+'</span>').join('')+'</div>')+'<div class="ga-actions">'+button('gaHide','I’m ready to answer','我准备好回答了')+'</div>');$('gaHide').onclick=()=>{clearInterval(clock);beginAnswer()};return}
 if(g.type==='recall')renderRecall(g);else renderDrawing(g)
}
function renderDots(g){const label=i=>g.mode==='letters'?String.fromCharCode(65+i):String(i+1);shell('<p>'+T('Tap or drag through the dots in order. Next: ','按顺序轻点或拖过圆点。下一个：')+'<strong>'+label(g.next)+'</strong></p><div class="ga-dotboard"><svg viewBox="0 0 100 100" aria-hidden="true"><polyline points="'+g.points.slice(0,g.next).map(p=>p.join(',')).join(' ')+'" fill="none" stroke="currentColor" stroke-width="1"/></svg>'+g.points.map((p,i)=>'<button class="ga-dot '+(i<g.next?'done':'')+'" data-dot="'+i+'" style="left:'+p[0]+'%;top:'+p[1]+'%" aria-label="'+label(i)+'" aria-pressed="'+(i<g.next)+'">'+label(i)+'</button>').join('')+'</div><div class="ga-actions">'+button('gaHint','Hint','提示')+button('gaUndo','Undo','撤销')+'</div>');const hit=i=>{if(g.paused||g.finished)return;if(i!==g.next){beep(300,.22,'sine');message(T('Look for ','请找 ')+label(g.next));return}g.next++;if(g.next===g.points.length){shell('<h2>'+T(g.shape.en,g.shape.zh)+'</h2>'+svgShape(g.shape)+'<div class="ga-actions">'+button('gaDone','Finish','完成')+'</div>');$('gaDone').onclick=()=>finish();return}const board=document.querySelector('.ga-dotboard');board.previousElementSibling.querySelector('strong').textContent=label(g.next);board.querySelector('polyline').setAttribute('points',g.points.slice(0,g.next).map(p=>p.join(',')).join(' '));board.querySelectorAll('[data-dot]').forEach(b=>{b.classList.toggle('done',+b.dataset.dot<g.next);b.setAttribute('aria-pressed',String(+b.dataset.dot<g.next));b.classList.remove('hint')})};document.querySelectorAll('[data-dot]').forEach(b=>b.onclick=e=>{if(e.detail===0)hit(+b.dataset.dot)});const board=document.querySelector('.ga-dotboard');board.onpointerdown=e=>{const b=e.target.closest('[data-dot]');if(b){board.setPointerCapture?.(e.pointerId);hit(+b.dataset.dot)}};board.onpointermove=e=>{if(e.buttons){const b=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-dot]');if(b&&+b.dataset.dot===g.next)hit(g.next)}};$('gaUndo').onclick=()=>{g.next=Math.max(0,g.next-1);renderDots(g)};$('gaHint').onclick=()=>{g.hints++;const b=document.querySelector('[data-dot="'+g.next+'"]');b.classList.add('hint');b.focus();message(T('The highlighted dot is next.','下一个是高亮的圆点。'))}}
function renderLinks(g){shell('<p>'+T('Select a symbol, then tap adjacent squares to reach its twin. Paths cannot cross; empty squares are allowed.','选择符号，再轻点相邻格子连接相同符号。路线不能交叉，可以留下空格。')+'</p><div class="ga-linkboard" style="--n:'+g.n+'"><svg viewBox="0 0 '+g.n+' '+g.n+'" aria-hidden="true">'+g.paths.map((p,i)=>'<polyline points="'+p.map(v=>(v%g.n+.5)+','+(Math.floor(v/g.n)+.5)).join(' ')+'" stroke="'+colors[i]+'" stroke-width=".15" fill="none"/>').join('')+'</svg>'+Array.from({length:g.n*g.n},(_,v)=>{const i=g.ends.findIndex(p=>p.includes(v)),path=g.paths.findIndex(p=>p.includes(v));return '<button data-link="'+v+'" style="color:'+colors[i>=0?i:path>=0?path:0]+'" aria-label="'+T('Row ','行 ')+(Math.floor(v/g.n)+1)+T(', column ','，列 ')+(v%g.n+1)+(i>=0?', '+symbols[i]:'')+'">'+(i>=0?symbols[i]:path>=0?'·':'')+'</button>'}).join('')+'</div><div class="ga-actions">'+button('gaUndo','Undo','撤销')+button('gaReset','Clear paths','清除路线')+button('gaHint','Hint — reset paths','提示 — 重置路线')+'</div>');document.querySelectorAll('[data-link]').forEach(b=>b.onclick=()=>{if(g.paused)return;if(addLink(g,+b.dataset.link)){if(connected(g)){finish();return}renderLinks(g)}else message(T('Use an empty neighbouring square, without crossing another route.','请选择相邻空格，不要穿过其他路线。'))});$('gaUndo').onclick=()=>{if(g.history.length){g.paths=g.history.pop();g.selected=-1;renderLinks(g)}};$('gaReset').onclick=()=>{g.history.push(g.paths.map(p=>p.slice()));g.paths=g.paths.map(()=>[]);g.selected=-1;renderLinks(g)};$('gaHint').onclick=()=>{g.history.push(g.paths.map(p=>p.slice()));g.paths=g.solution.map((p,i)=>i===0?p.slice():[]);g.selected=-1;g.hints++;g.notice=T('Paths reset. The first pair shows one possible route.','路线已重置，第一对显示一条可行路线。');renderLinks(g)}}
