function scene(g,second){const c=i=>second&&g.changes.includes(i),v=g.variant;return '<svg viewBox="0 0 100 100" aria-hidden="true"><rect width="100" height="100" fill="'+['#dff3f9','#e9f3de','#fcead8'][v]+'"/><path d="M0 60Q30 42 55 61T100 55V100H0Z" fill="#bdd99c"/><path d="M38 100Q40 65 65 60" fill="none" stroke="#ead6a5" stroke-width="15"/><circle cx="78" cy="18" r="'+(c(0)?(g.subtle?8:5):9)+'" fill="#eaa834"/><g transform="translate(20 30)"><path d="M0 0v24" stroke="#78503c" stroke-width="4"/><circle cy="-2" r="13" fill="'+(c(1)?(g.subtle?'#6b9870':'#cf8c44'):'#4f8e63')+'"/></g><rect x="37" y="32" width="26" height="24" fill="#f5e2b8"/><path d="M33 32L50 18 67 32Z" fill="'+(['#b85445','#5d7990','#9b765a'][g.sceneTheme||0])+'"/><rect x="46" y="42" width="8" height="14" fill="#78503c"/>'+(c(2)&&g.subtle?'<rect x="41" y="35" width="4" height="6" fill="#4d87a1"/>':c(2)?'<circle cx="43" cy="38" r="3" fill="#4d87a1"/>':'<rect x="40" y="35" width="6" height="6" fill="#4d87a1"/>')+'<g transform="translate(79 47)"><ellipse rx="10" ry="4" fill="#507d9f"/>'+(c(3)?(g.subtle?'<path d="M-7 0Q0-9 7 0" fill="#f6f1db"/>':''):'<path d="M-8 0Q0-12 8 0" fill="#f6f1db"/>')+'</g><g transform="translate(20 67)"><path d="M0 0v16" stroke="#396d4e" stroke-width="2"/><g fill="'+(c(4)?(g.subtle?'#d56079':'#7957a8'):'#bd4767')+'"><circle cx="-4" r="4"/><circle cx="4" r="4"/><circle cy="-4" r="4"/><circle cy="4" r="4"/></g><circle r="2" fill="#f4cc5a"/></g><g transform="translate(50 74)"><rect x="-10" y="-5" width="20" height="5" rx="2" fill="#87634a"/><path d="M-7 0v8M7 0v8" stroke="#87634a" stroke-width="2"/>'+(c(5)?'<circle cy="-9" r="4" fill="#bd4767"/>':'')+'</g><g transform="translate(80 78)"><ellipse rx="10" ry="6" fill="#528d9d"/>'+(c(6)?'<path d="M-6 0h12" stroke="white"/>':'<path d="M-6-2h12M-6 2h12" stroke="white"/>')+'</g>'+(c(7)?'':'<path d="M42 12q4-4 7 0q4-4 7 0" fill="none" stroke="#3e6464" stroke-width="1.5"/>')+'</svg>'}
function renderSpot(g){const panel=(second)=>'<figure class="ga-picture '+(!second&&g.zoom?'ga-original-hidden':'')+'"><figcaption>'+T(second?'Find changes here':'Original',second?'在此找不同':'原图')+'</figcaption><div class="ga-scene">'+scene(g,second)+(second?regions.map((p,i)=>'<button class="ga-region '+(g.found.includes(i)?'found':'')+'" data-spot="'+i+'" style="left:'+p[0]+'%;top:'+p[1]+'%" aria-label="'+T('Check picture area ','检查图片区域 ')+(i+1)+'">'+(g.found.includes(i)?'✓':'')+'</button>').join(''):g.found.map(i=>'<span class="ga-mark" style="left:'+regions[i][0]+'%;top:'+regions[i][1]+'%">✓</span>').join(''))+'</div></figure>';shell('<p>'+g.found.length+' / '+g.changes.length+' '+T('differences found. Tap changes in the second picture.','处不同已找到。请轻点第二张图的不同处。')+'</p><div class="ga-pictures '+(g.zoom?'zoom':'')+'">'+panel(false)+panel(true)+'</div><div class="ga-actions">'+button('gaZoom',g.zoom?'Show both pictures':'Enlarge pictures',g.zoom?'显示两张图':'放大图片')+button('gaHint','Hint','提示')+(g.found.length===g.changes.length?button('gaDone','Finish','完成'):'')+'</div>');document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{if(g.paused||g.finished)return;const i=+b.dataset.spot;if(g.found.includes(i))return;if(g.changes.includes(i)){g.found.push(i);chime();g.notice=T('Well spotted!','找到了！');renderSpot(g);}else{beep(300,.22,'sine');message(T('That area is the same. Keep looking.','这一处相同，请继续观察。'))}});if($('gaDone'))$('gaDone').onclick=()=>finish();$('gaZoom').onclick=()=>{g.zoom=!g.zoom;renderSpot(g)};$('gaHint').onclick=()=>{g.hints++;const i=g.changes.find(i=>!g.found.includes(i));if(i!==undefined){document.querySelector('[data-spot="'+i+'"]').classList.add('hint');message(T('Look in the outlined area.','请观察边框标出的区域。'))}}}
function tokens(text,g){text=text.trim().toLocaleLowerCase().normalize('NFKC');return g.mode==='numbers'?text.replace(/[\s,，-]/g,'').split(''):text.split(/[\s,，、]+/u).filter(Boolean)}
function renderRecall(g){if(g.phase==='review'){shell('<h2>'+T('Your recall','您的回忆')+'</h2><p>'+g.correct+' / '+g.answer.length+' '+T('positions correct','个位置正确')+'</p><ol class="ga-recall-review">'+g.answer.map((x,i)=>'<li>'+esc(x)+' — '+(g.entered[i]===x.toLocaleLowerCase()?'✓':T('You entered: ','您输入：')+esc(g.entered[i]||'—'))+'</li>').join('')+'</ol><div class="ga-actions">'+button('gaDone','Finish','完成')+'</div>');$('gaDone').onclick=()=>finish(g.correct/Math.max(g.answer.length,g.entered.length));return}shell('<form id="gaRecallForm"><label for="gaAnswer">'+T('Type the sequence in the same order. Separate words with spaces.','按原顺序输入，词语之间用空格分开。')+'</label><input id="gaAnswer" autocomplete="off" autocapitalize="off" spellcheck="false" inputmode="'+(g.mode==='numbers'?'numeric':'text')+'" aria-label="'+T('Your remembered sequence','您记住的顺序')+'">'+(g.mode==='numbers'?'<div class="ga-keypad">'+['1','2','3','4','5','6','7','8','9','⌫','0'].map(n=>'<button type="button" class="btn" data-key="'+n+'">'+n+'</button>').join('')+'</div>':'')+'<div class="ga-actions"><button class="btn main" type="submit">'+T('Check answer','检查答案')+'</button><button class="btn" type="button" id="gaStudy">'+T('Look again','再看一次')+'</button></div></form>');document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const input=$('gaAnswer');input.value=b.dataset.key==='⌫'?input.value.slice(0,-1):input.value+b.dataset.key});$('gaStudy').onclick=()=>{g.hints++;beginView()};$('gaRecallForm').onsubmit=e=>{e.preventDefault();if(g.paused||g.phase==='review')return;g.entered=tokens($('gaAnswer').value,g);if(!g.entered.length){message(T('Enter a number or word first.','请先输入数字或词语。'));return}g.correct=g.answer.filter((x,i)=>x.toLocaleLowerCase()===g.entered[i]).length;g.correct===g.answer.length&&g.entered.length===g.answer.length?chime():beep(300,.22,'sine');g.phase='review';renderRecall(g)}}
function renderDrawing(g){if(g.phase==='review'){shell('<h2>'+T(g.recognition?(g.score===1?'Correct shape!':'Let’s compare the shapes'):'Compare your drawing',g.recognition?(g.score===1?'图形正确！':'一起比较图形'):'比较您的画图')+'</h2><p>'+T(g.recognition?'Shape choice score: ':'Approximate shape match: ',g.recognition?'图形选择得分：':'大致形状相似度：')+Math.round(g.score*100)+'% — '+T('a gentle guide, not a handwriting test.','仅供参考，不是书写测试。')+'</p><div class="ga-pictures"><figure><figcaption>'+T('Original','原图')+'</figcaption>'+svgShape(g.shape)+'</figure><figure><figcaption>'+T('Your drawing','您的画图')+'</figcaption><svg class="ga-shape" viewBox="0 0 100 100">'+g.strokes.map(s=>'<polyline points="'+s.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="currentColor" stroke-width="2"/>').join('')+'</svg></figure></div><div class="ga-actions">'+button('gaDone','Finish','完成')+'</div>');$('gaDone').onclick=()=>finish(g.score);return}
 if(g.recognition){shell('<p>'+T('Choose the shape you saw.','请选择刚才看到的图形。')+'</p><div class="ga-shape-options">'+g.choices.map((s,i)=>'<button class="btn" data-shape="'+i+'" aria-label="'+T(s.en,s.zh)+'">'+svgShape(s)+'</button>').join('')+'</div>');document.querySelectorAll('[data-shape]').forEach(b=>b.onclick=()=>{g.score=g.choices[+b.dataset.shape]===g.shape?1:0;g.strokes=[g.choices[+b.dataset.shape].p];g.phase='review';renderDrawing(g)});return}
 shell('<p>'+T('Draw the shape from memory. Shaky lines are welcome.','凭记忆画出图形，线条不直也没关系。')+'</p><svg id="gaCanvas" viewBox="0 0 100 100" aria-label="'+T('Drawing area; use Choose a shape for keyboard play.','绘图区；键盘操作请选择“选择图形”。')+'">'+g.strokes.map(s=>'<polyline points="'+s.map(p=>p.join(',')).join(' ')+'"/>').join('')+'</svg><div class="ga-actions">'+button('gaUndo','Undo stroke','撤销笔画')+button('gaClear','Clear','清除')+button('gaCheck','Compare','比较')+button('gaChoice','Choose a shape instead','改为选择图形')+button('gaStudy','Look again','再看一次')+'</div>');const canvas=$('gaCanvas');let stroke=null,line=null,pointer=null;const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100)),Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100))]};canvas.onpointerdown=e=>{if(g.paused||pointer!==null||e.isPrimary===false)return;e.preventDefault();pointer=e.pointerId;canvas.setPointerCapture?.(e.pointerId);stroke=[point(e)];g.strokes.push(stroke);line=document.createElementNS('http://www.w3.org/2000/svg','polyline');canvas.append(line)};canvas.onpointermove=e=>{if(!stroke||g.paused||e.pointerId!==pointer)return;e.preventDefault();stroke.push(point(e));line.setAttribute('points',stroke.map(p=>p.join(',')).join(' '))};canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=e=>{if(e.pointerId!==pointer)return;pointer=null;stroke=null;line=null};canvas.addEventListener('touchmove',e=>e.preventDefault(),{passive:false});$('gaUndo').onclick=()=>{g.strokes.pop();renderDrawing(g)};$('gaClear').onclick=()=>{g.strokes=[];renderDrawing(g)};$('gaCheck').onclick=()=>{if(!g.strokes.some(s=>s.length>2)){message(T('Draw a shape first, or choose the shape alternative.','请先画图，或使用选择图形方式。'));return}g.score=drawingScore(g.strokes,g.shape.p);g.phase='review';renderDrawing(g)};$('gaChoice').onclick=()=>{g.recognition=true;g.choices=shuffle([g.shape,...shuffle(shapes.filter(s=>s!==g.shape)).slice(0,3)]);renderDrawing(g)};$('gaStudy').onclick=()=>{g.hints++;beginView()}}
