function render(){const g=active;if(!g)return;g.phase='answer';g.answered=false;g.helped=false;g.question=g.id==='today'?todayQuestions(new Date(),g.opts.zone,g.opts.country)[g.questions[g.index]]:g.questions[g.index];const item=g.question;let choices=item.choices.filter(x=>x!==item.answer).slice(0,g.level===1?2:3);choices=shuffle([item.answer,...choices]);shell('<p>'+T('Question ','第 ')+(g.index+1)+' / '+g.questions.length+'</p><h2>'+esc(item.prompt)+'</h2>'+(item.icon?'<div class="ed-food-art" aria-hidden="true">'+(window.MindGardenArt?.html(item.icon)||item.icon)+'</div>':'')+(g.id==='today'?'<p class="ed-context">'+T('Based on the selected time zone when this question appeared.','按此题出现时所选时区的时间作答。')+(item.input==='time'?' '+T('Within 5 minutes is accepted.','相差5分钟以内均可。'):'')+'</p>':'')+(g.opts.style==='type'?'<form id="edForm"><label>'+T('Your answer','您的答案')+'<input id="edAnswer" autocomplete="off" type="'+(item.input||'text')+'" required></label>'+button('edCheck','Check answer','检查答案')+'</form>':'<div class="ed-choices">'+choices.map((x,i)=>'<button class="btn" data-ed="'+i+'">'+esc(x)+'</button>').join('')+'</div>')+'<p id="edFeedback" class="ga-notice" role="status"></p><div class="ga-actions">'+button('edHint','Show answer','显示答案')+button('edSkip','Skip','跳过')+button('edNext','Next','下一题')+'</div>');$('edNext').hidden=true;document.querySelectorAll('[data-ed]').forEach(b=>b.onclick=()=>answer(choices[+b.dataset.ed]));if($('edForm'))$('edForm').onsubmit=e=>{e.preventDefault();answer($('edAnswer').value)};$('edHint').onclick=()=>{g.helped=true;answer(item.answer)};$('edSkip').onclick=()=>{g.helped=true;answer('')};$('edNext').onclick=next;}
function matches(item,value){if(item.input==='time'&&/^\d{2}:\d{2}$/.test(value)){const [h,m]=value.split(':').map(Number);if(h>23||m>59)return false;const delta=Math.abs(h*60+m-item.minutes);return Math.min(delta,1440-delta)<=5}return value.trim().normalize('NFKC').toLocaleLowerCase()===item.answer.normalize('NFKC').toLocaleLowerCase()}
function answer(value){const g=active;if(!g||g.paused||g.answered)return;g.answered=true;const ok=matches(g.question,value);if(ok&&!g.helped)g.correct++;if(!g.helped){ok?chime():beep(300,.22,'sine')}$('edFeedback').textContent=(g.helped?T('Let’s remember: ','一起记住：'):ok?T('That’s right: ','答对了：'):T('The answer is: ','答案是：'))+g.question.answer+(value?T(' · Your answer: ',' · 您的答案：')+value:'');document.querySelectorAll('[data-ed],#edCheck,#edHint,#edSkip,#edAnswer').forEach(b=>b.disabled=true);$('edNext').hidden=false;$('edNext').focus();}
