function pause(menu=false){const g=active;if(!g)return;if(g.finished){if(menu)exit();return}g.paused=true;overlay('<h2>'+(menu?T('Game menu','游戏菜单'):T('Paused','已暂停'))+'</h2>'+button('edResume','Resume','继续')+(menu?'<p>'+T('Leave this unfinished round and return to the library?','离开尚未完成的一局并返回游戏库？')+'</p>'+button('edLeave','Leave game','退出游戏'):''));$('edResume').onclick=()=>{closeOv();g.paused=false};if($('edLeave'))$('edLeave').onclick=exit;}
