/* pilot.js */
/* Pilot tools: on-device, opt-in usage counts; server-backed room summaries. */
(function(){
'use strict';
const T=(en,zh)=>window.MindGardenLocale.pair(en,zh),$=id=>document.getElementById(id);
const KEY='mindGardenPilotUsage';let data={enabled:false,events:[]};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&Array.isArray(saved.events))data=saved}catch{}
function saveUsage(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{window.reportStorageFailure?.()}}
function event(kind,activity,level){if(!data.enabled)return;data.events.push({day:new Date().toISOString().slice(0,10),kind,activity:String(activity||'unknown').slice(0,40),level:Number(level)||null});data.events=data.events.slice(-500);saveUsage()}
// Record only structured activity identifiers, never names, answers or tokens.
for(const key of ['startMG']){const original=window[key];if(original)window[key]=function(id,...args){event('start',id);return original.call(this,id,...args)}}
const originalLog=window.logPlay;if(originalLog)window.logPlay=function(id,r,s,details){const result=originalLog.apply(this,arguments);event('complete',id,details?.level);return result};
window.addEventListener('gardenRoomState',e=>{const s=e.detail;if(s.finished)eventOnce(s)});
const seen=new Set();function eventOnce(s){const k=s.code+':'+s.round;if(seen.has(k))return;seen.add(k);event('group-round-complete',s.mode)}
const csvCell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';
function download(rows,name){const blob=new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function usage(){window.overlay('<section class="pilot-panel"><h2>'+T('Pilot activity log','试用活动记录')+'</h2><p>'+T('Optional, stored only in this browser. Records activity identifiers, dates and completion events. No names, answers or session tokens. Nothing is uploaded. Keeps the latest 500 events.','可选功能，仅保存在此浏览器。记录活动编号、日期及完成事件，不包含姓名、答案或会话令牌，不会上传。保留最近500条。')+'</p><label class="pilot-opt"><input id="pilotOpt" type="checkbox"'+(data.enabled?' checked':'')+'>'+T('Enable local pilot logging','启用本地试用记录')+'</label><p>'+data.events.length+' '+T(data.events.length===1?'event recorded':'events recorded','条记录')+'</p><p class="tip">'+T('Launch counts cover the main mini-games; completion counts cover activities using the shared results system. This is not a complete abandonment or error report.','开始次数涵盖主要小游戏，完成次数涵盖使用共用成绩系统的活动。这不是完整的退出或错误报告。')+'</p><div class="row"><button class="btn" id="pilotUsageExport">'+T('Export CSV','导出CSV')+'</button><button class="btn" id="pilotUsageClear">'+T('Clear records','清除记录')+'</button><button class="btn" id="pilotUsageClose">'+T('Close','关闭')+'</button></div></section>');$('pilotOpt').onchange=e=>{data.enabled=e.target.checked;saveUsage()};$('pilotUsageExport').onclick=()=>download([['day','event','activity','level'],...data.events.map(e=>[e.day,e.kind,e.activity,e.level])],'mind-garden-pilot-usage.csv');$('pilotUsageClear').onclick=()=>{if(confirm(T('Delete local pilot activity records?','删除本地试用活动记录？'))){data.events=[];saveUsage();usage()}};$('pilotUsageClose').onclick=closeOv}
async function summary(state,back){
 window.overlay('<section class="pilot-panel"><h2>'+T('Session summary','活动摘要')+'</h2><p role="status">'+T('Loading saved participation…','正在读取已保存的参与记录……')+'</p><button class="btn" id="pilotSummaryBack">'+T('Back to room','返回房间')+'</button></section>');const view=$('pilotSummaryBack');view.onclick=back;
 try{const report=await window.MindGardenMultiplayer.summaryData(state.code);if(!view.isConnected)return;
 const minutes=Math.max(0,Math.round(((state.endedAt||state.serverTime)-state.createdAt)/60000));
 window.overlay('<section class="pilot-panel" id="pilotReport"><p class="pilot-eyebrow">Mind Garden</p><h2>'+T('A lovely session together','一起度过美好时光')+'</h2><p>'+T('Room ','房间 ')+esc(state.code)+'</p><div class="pilot-stats"><strong>'+report.players.length+' '+T(report.players.length===1?'participant':'participants','位参与者')+'</strong><strong>'+report.rounds.length+' '+T(report.rounds.length===1?'round':'rounds','轮活动')+'</strong><strong>'+minutes+' '+T(minutes===1?'minute including setup':'minutes including setup','分钟（含准备）')+'</strong></div><div class="pilot-rounds">'+report.rounds.slice().reverse().map(r=>'<div><span>'+T('Round ','第 ')+r.round+' · '+esc(window.MindGardenMultiplayer.activityName(r.mode))+'</span><strong>'+r.completed+'/'+r.results.length+' '+T('completed','已完成')+'</strong></div>').join('')+'</div><p>'+T('Participation summary • No health assessment. Unfinished rounds are not failures.','参与摘要 · 非健康评估。未完成不代表失败。')+'</p><div class="row pilot-no-print"><button class="btn main" id="pilotPrint">'+T('Print summary','打印摘要')+'</button><button class="btn" id="pilotExport">'+T('Export CSV','导出CSV')+'</button><button class="btn" id="pilotBack">'+T('Back to room','返回房间')+'</button></div></section>');
 $('pilotBack').onclick=back;$('pilotPrint').onclick=()=>{document.body.classList.add('pilot-print');window.print()};$('pilotExport').onclick=()=>download([['round','activity','completed','participants'],...report.rounds.map(r=>[r.round,r.mode,r.completed,r.results.length])],'mind-garden-session-summary.csv');
 }catch(e){if(view.isConnected)view.previousElementSibling.textContent=e.message}
}
window.addEventListener('afterprint',()=>document.body.classList.remove('pilot-print'));
window.MindGardenPilot={usage,summary,event,csvCell};
})();

;
/* layout-switch.js */
/* A layout preference, not a second copy of the games or stored data. */
(function(){'use strict';
function apply(){document.documentElement.dataset.layout=save.layout==='classic'?'classic':'modern';}
function set(layout){
 if(!['classic','modern'].includes(layout))return false;
 if(document.getElementById('home').classList.contains('hidden')||!document.getElementById('ov').classList.contains('hidden'))return false;
 save.layout=layout;persist();apply();window.MindGardenDashboard.refresh();return true;
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-layout-choice]');if(button)set(button.dataset.layoutChoice)});
window.addEventListener('gardenPlayerChange',apply);apply();
window.MindGardenLayout={set,get:()=>save.layout==='classic'?'classic':'modern'};
})();
